tools.isDiscoverable:
(ctx) => {
    if (!ctx.subagentThreadId && ctx.canUseExplorerSubagent) return false;

    const exploreCodeAvailable =
      ctx.subagentPersona === "explorer" &&
      readSettings().enableCodeExplorer === true &&
      isCodeExplorerReady(ctx.appPath);
    return !exploreCodeAvailable;
  }

tools.isEnabled:
(ctx) => {
    const settings = ctx.inferenceSettings ?? readSettings();
    return (
      Boolean(getDirectSearchConfig(settings)) ||
      (settings.proModelUsage !== "api-key" &&
        settings.proModelUsage !== "subscription" &&
        ctx.isDyadPro &&
        !ctx.freeModelMode)
    );
  }

